func (a *headAppender) evaluateHistogramAppendability(s *memSeries, t int64, h *histogram.Histogram, headMaxt, minValidTime, oooTimeWindow int64, oooHistogramsEnabled bool) (isOOO bool, oooDelta int64, err error) {
	if t >= minValidTime {
		if s.headChunks == nil {
			return false, 0, nil
		}
		msMaxt := s.maxTime()
		if t > msMaxt {
			return false, 0, nil
		}
		if t == msMaxt {
			if !h.Equals(s.lastHistogramValue) {
				return false, 0, storage.ErrDuplicateSampleForTimestamp
			}
			return false, 0, nil
		}
	}
	if oooTimeWindow > 0 && t >= headMaxt-oooTimeWindow {
		if !oooHistogramsEnabled {
			return true, headMaxt - t, storage.ErrOOONativeHistogramsDisabled
		}
		return true, headMaxt - t, nil
	}
	if oooTimeWindow > 0 {
		return true, headMaxt - t, storage.ErrTooOldSample
	}
	if t < minValidTime {
		return false, headMaxt - t, storage.ErrOutOfBounds
	}
	return false, headMaxt - t, storage.ErrOutOfOrderSample
}

