func (a *headAppender) insertOutOfOrderSample(s *memSeries, t int64, v float64, h *histogram.Histogram, fh *histogram.FloatHistogram, chunkDiskMapper *chunks.ChunkDiskMapper, oooCapMax int64, logger *slog.Logger) (inserted, chunkCreated bool, mmapRefs []chunks.ChunkDiskMapperRef) {
	if s.ooo == nil {
		s.ooo = &memSeriesOOOFields{}
	}
	c := s.ooo.oooHeadChunk
	if c == nil || c.chunk.NumSamples() == int(oooCapMax) {
		c, mmapRefs = a.cutSeriesOOOHeadChunk(s, t, chunkDiskMapper, logger)
		chunkCreated = true
	}
	ok := c.chunk.Insert(t, v, h, fh)
	if ok {
		if chunkCreated || t < c.minTime {
			c.minTime = t
		}
		if chunkCreated || t > c.maxTime {
			c.maxTime = t
		}
	}
	return ok, chunkCreated, mmapRefs
}

func (a *headAppender) appendInOrderFloat(s *memSeries, t int64, v float64, appendID uint64, o chunkOpts) (sampleInOrder, chunkCreated bool) {
	c, sampleInOrder, chunkCreated := a.prepareXORHeadChunk(s, t, chunkenc.EncXOR, o)
	if !sampleInOrder {
		return sampleInOrder, chunkCreated
	}
	s.app.Append(t, v)
	c.maxTime = t
	s.lastValue = v
	s.lastHistogramValue = nil
	s.lastFloatHistogramValue = nil
	if appendID > 0 {
		s.txs.add(appendID)
	}
	return true, chunkCreated
}

